local cs_coroutine = require("XLua.cs_coroutine")
local OverseaMallFurnitureDialog = Class('OverseaMallFurnitureDialog')
---@type OverseaStoreMgr
local OverseaStoreMgr = import('Game.OverseaStore.OverseaStoreMgr'):GetInstance()

function OverseaMallFurnitureDialog:__init()
    self.currencyId = nil
end

function OverseaMallFurnitureDialog:__delete()
    self.currencyId = nil
end

function OverseaMallFurnitureDialog:OnDisable()
    if self.nodeEnv then
        self.nodeEnv:OnDisable()
    end
end

function OverseaMallFurnitureDialog:Awake()
    local nodeEnv = CfUtils.GetLuaScr(self.Cell.gameObject,"Game.OverseaStore.Cell.OverseaMallFurnitureDialogCell")
    if not isNull(nodeEnv) then
        self.nodeEnv = nodeEnv
    end
end

--region public
---刷新
---@param storeType OverseaStoreConstants.StoreType
function OverseaMallFurnitureDialog:Refresh(storeType)
    self:SetStoreType(storeType)
    self:RefreshShow()
end

--region public
---刷新
---@param storeType OverseaStoreConstants.StoreType
function OverseaMallFurnitureDialog:SetDelegate(delegate)
    self.delegate = delegate
end

function OverseaMallFurnitureDialog:RefreshCurrencyBar()
    if isNotNull(self.currencyId) then
        CfUtils.RefreshTopGoods({Constants.Currency.FreeDiamondId, self.currencyId})
    end
end

function OverseaMallFurnitureDialog:RefreshShow()
    local subIndex = self.delegate:GetSelectedSubTab()
    local data
    local storeData = OverseaStoreMgr:GetStoreDataByType(self._storeType)

    ---@type OverseaStoreMgr
    local OverseaStoreMgr = import('Game.OverseaStore.OverseaStoreMgr'):GetInstance()
    for i, v in ipairs(storeData.products) do
        OverseaStoreMgr:AddRenovateShopRedPointId(v.productId)
    end
    GameUtils.SetRedPointNum(Constants.RedPointConst.OverseaStoreRenovate,  0)
    Events.Broadcast(Constants.EventNames.OVERSEA_STORE_RED_POINT_REFRESH)
    if not isNull(subIndex) and checkNumber(subIndex) > 0 then
        if not isNull(storeData) then
            local tempData = storeData.products[subIndex]
            if tempData then
                data = tempData
            end
        end
    else
        data = storeData.products[1]
    end
    self.nodeEnv:RefreshShow(data)
    
    if table.count(checkTable(data.prices)) > 0 then
        self.currencyId = data.prices[1].currency
        CfUtils.RefreshTopGoods({Constants.Currency.FreeDiamondId, self.currencyId})
    end
end

--region get / set
---设置商店类型
function OverseaMallFurnitureDialog:SetStoreType(storeType)
    self._storeType = storeType
end

---获取商店类型
function OverseaMallFurnitureDialog:GetStoreType()
    return self._storeType
end

function OverseaMallFurnitureDialog:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
end

return OverseaMallFurnitureDialog